// W1: map a WooCommerce order/customer webhook payload to a Mautic contact body.
// Mautic /contacts/new upserts on email (verified 2026-06-02). Keys are Mautic field aliases.
const items = $input.all();
const results = [];
for (const item of items) {
  const root = item.json || {};
  // n8n Webhook node nests the HTTP payload under `body`.
  const b = (root.body && typeof root.body === 'object') ? root.body : root;
  const billing = b.billing || {};
  const email = String(b.email || billing.email || '').trim().toLowerCase();
  // No email => cannot upsert into Mautic. Skip safely (do not error).
  if (!email) { continue; }
  const isOrder = Array.isArray(b.line_items);
  const firstname = b.first_name || billing.first_name || '';
  const lastname = b.last_name || billing.last_name || '';
  const phone = billing.phone || b.phone || '';
  const wcCustomerId = isOrder ? b.customer_id : b.id;
  const courses = isOrder ? (b.line_items || []).map(li => (li && li.name ? String(li.name).trim() : '')).filter(Boolean) : [];
  const courseInterest = courses.join(', ');
  // Mautic datetime fields expect "Y-m-d H:i:s".
  const rawDate = b.date_created || b.date_created_gmt || '';
  let lastPurchaseDate = '';
  if (isOrder && rawDate) { lastPurchaseDate = String(rawDate).replace('T', ' ').slice(0, 19); }
  // Only include non-empty fields so we never blank existing Mautic data on update.
  // NOTE: source_channel is intentionally NOT set — a purchase does not reveal the
  // contact's acquisition channel; overwriting it would corrupt attribution.
  const contact = { email, tags: ['wc-customer'] };
  if (firstname) contact.firstname = firstname;
  if (lastname) contact.lastname = lastname;
  if (phone) contact.phone = phone;
  const wcIdNum = Number(wcCustomerId);
  if (Number.isFinite(wcIdNum) && wcIdNum > 0) { contact.wc_customer_id = wcIdNum; }
  if (courseInterest) contact.course_interest = courseInterest;
  if (lastPurchaseDate) contact.last_purchase_date = lastPurchaseDate;
  results.push({ json: contact });
}
return results;

